//Union-Find Tree



template<class T> struct UFT{

  vector<int> par;

  vector<int> rank;

  vector<T> diff_weight;



  UFT(int n = 1, T w = 0) {

    init(n, w);

  }



  void init(int n = 1, T w = 0) {

    par.resize(n);

    rank.resize(n);

    diff_weight.resize(n);

    rep(i, 0, n){

      par[i] = i;

      rank[i] = 0;

      diff_weight[i] = w;

    }

  }



  int root(int x){

    if(par[x] == x){

      return x;

    }else{

      int r = root(par[x]);

      diff_weight[x] += diff_weight[par[x]];

      return par[x] = r;

    }

  }



  bool unite(int x, int y, int w = 0){

    w += weight(x); w -= weight(y);

    x = root(x);

    y = root(y);

    if(x == y) return false;

    if(rank[x] < rank[y]){

      par[x] = y;

      diff_weight[x] = -w;

    }else{

      par[y] = x;

      diff_weight[y] = w;

      if(rank[x] == rank[y]) rank[x]++;

    }

    return true;

  }



  bool same(int x, int y){

    return root(x) == root(y);

  }



  T weight(int x) {

    root(x);

    return diff_weight[x];

  }



  T diff(int x, int y) {

    return weight(y) - weight(x);

  }

};



