int n;



int ghead[100010];

int gnext[200010];

int gto[200010];



int path[100010];

int npath;



int col[100010];



bool DFS(int x,int pre)

{

	if(x==n-1)

	{

		npath=0;

		path[npath++]=x;



		return 1;

	}



	for(int v=ghead[x];v!=-1;v=gnext[v])

	{

		int to=gto[v];



		if(to==pre)continue;

		else

		{

			if(DFS(to,x))

			{

				path[npath++]=x;



				return 1;

			}

			else continue;

		}

	}



	return 0;

}



void DFScol(int x,int pre)

{

	for(int v=ghead[x];v!=-1;v=gnext[v])

	{

		int to=gto[v];



		if(to==pre||col[to]!=-1)continue;

		else

		{

			col[to]=col[x];



			DFScol(to,x);

		}

	}

}



void Add(int x,int y,int flag,int i)

{

	gnext[2*i+flag]=ghead[x];

	ghead[x]=2*i+flag;

	gto[2*i+flag]=y;

}



int cnt1,cnt2;



int main(int argc, char const *argv[])

{

	ios::sync_with_stdio(false);



	scanf("%d",&n);



	for(int i=0;i<n;i++)ghead[i]=-1;



	for(int i=0;i<n-1;i++)

	{

		int x,y;

		scanf("%d%d",&x,&y);



		x--,y--;



		Add(x,y,0,i);

		Add(y,x,1,i);

	}



	assert(DFS(0,-2));



	reverse(path,path+npath);



	for(int i=0;i<n;i++)col[i]=-1;



	for(int i=0;i<npath;i++)col[path[i]]=((i<(npath+1)/2) ? 0 : 1);



	for(int i=0;i<npath;i++)DFScol(path[i],-1);



	for(int i=0;i<n;i++)

	{

		if(col[i]==0)cnt1++;

		else cnt2++;

	}



	printf("%s",(cnt1>cnt2 ? "Fennec" : "Snuke"));



	//printf("Time used = %.12f",(double)(clock())/CLOCKS_PER_SEC);

	return 0;

}

