inline INT& dp(int i,int j,int k)

{

	if(k>=0)return dpz[i][j][k];

	else return dpf[i][j][-k];

}



int main()

{

	scanf("%d%d",&n,&m);

	for(int i=1;i<=n;i++)

	{

		scanf("%d%d",w+i,v+i);

		if(i==1)bw=w[i];

		w[i]-=bw;

	}

	for(int i=0;i<=n;i++)

		for(int j=0;j<=n;j++)

			for(int k=-333;k<=333;k++)

				dp(i,j,k)=-INF;

	dp(0,0,0)=0;

	INT ans=0;

	for(int i=1;i<=n;i++)

		for(int j=0;j<=n;j++)

			for(int k=-307;k<=307;k++)

			{

				dp(i,j,k)=dp(i-1,j,k);

				if(j>0)dp(i,j,k)=max(dp(i,j,k),dp(i-1,j-1,k-w[i])+v[i]);

				if(1LL*j*bw+k<=1LL*m)ans=max(ans,dp(i,j,k));

			}

