struct UnionFind {

	vector<int> A;

	UnionFind(int n) : A(n, -1) {}

	int find(int x) {

		if (A[x] < 0) return x;

		return A[x] = find(A[x]);

	}

	void unite(int x, int y) {

		x = find(x), y = find(y);

		if (x == y) return;

		if (A[x] > A[y]) swap(x, y);

		A[x] += A[y];

		A[y] = x;

	}

	int ngroups() {

		int ans = 0;

		for (auto a : A) if (a < 0) ans++;

		return ans;

	}

};

