long long mod=1e9+7;

long long no[180],ans[180];

map<long long,long long> mp;

long long f(long long k)

{

    if (mp[k]) return mp[k];

    for(int i=1;i<=177;i++)

        if (k==no[i]) return mp[k]=ans[i];

    if (k%2==0) return mp[k]=(2*f(k/2-1)+f(k/2))%mod;

    return mp[k]=(f(k/2-1)+2*f(k/2))%mod;

}

