     {

          no[3*i-2]=(1ll<<i)-2;

          no[3*i-1]=no[3*i-2]+1;

          no[3*i]=no[3*i-1]+1;

          ans[3*i-2]=(2*ans[3*i-5]+ans[3*i-4])%mod;

          ans[3*i-1]=(ans[3*i-5]+2*ans[3*i-4])%mod;

          ans[3*i]=(ans[3*i-1]+i+1)%mod;

     }

