inline double c_dist(int i,int j){

    double d = hypot(x[i]-x[j],y[i]-y[j]);

    return max(d-(r[i]+r[j]),0.0);

}

double solve(){

    ll xs,ys,xt,yt; cin >> xs >> ys>> xt >> yt;

    int N; cin >> N;

    x[0] = xs; y[0] = ys; r[0] = 0;

