    vector<vector<edge>> G(N+2);

    for(int i = 0; i < N+2;i++){

        for(int j = i+1; j < N+2;j++){

            double d = c_dist(i,j);

            G[i].push_back(edge(i,j,d));

            G[j].push_back(edge(j,i,d));

