void rd(int &x) {

	int k;

	x = 0;

	for (;;) {

		k = getchar_unlocked();

		if ('0' <= k && k <= '9') {

			x = k - '0';

			break;

		}

	}

	for (;;) {

		k = getchar_unlocked();

		if (k < '0' || k > '9') {

			break;

		}

		x = x * 10 + k - '0';

	}

}



