bool check(int x, int n) {

	// debug("check %d\n", x);

	for(int i = 1; i <= n; i++)

		b[i] = a[i] > x;

	int mid = (1 + n) >> 1;

	for(int i = 0; i < mid; i ++) {

		if(b[mid + i] == b[mid + i + 1])

			return b[mid + i];

		if(b[mid - i] == b[mid - i - 1])

			return b[mid - i];

	}

	return b[n];

}



