    int cnt = 0;

    for(auto &to : g[idx]) {

      if(!used[to]) {

        ++cnt;

        k = dfs(to, k, idx);

        low[idx] = min(low[idx], low[to]);

        is_articulation |= ~par && low[to] >= ord[idx];

        if(ord[idx] < low[to]) bridge.emplace_back(minmax(idx, (int) to));

      } else if(to != par) {

        low[idx] = min(low[idx], ord[to]);

      }

    }

    is_articulation |= par == -1 && cnt > 1;

    if(is_articulation) articulation.push_back(idx);

    return k;

  }



  virtual void build() {

    used.assign(g.size(), 0);

    ord.assign(g.size(), 0);

    low.assign(g.size(), 0);

    int k = 0;

    for(int i = 0; i < g.size(); i++) {

      if(!used[i]) k = dfs(i, k, -1);

    }

  }

};





template< typename G >

struct BiConnectedComponents : LowLink< G > {

  using LL = LowLink< G >;



  vector< int > used;

  vector< vector< pair< int, int > > > bc;

  vector< pair< int, int > > tmp;



  BiConnectedComponents(const G &g) : LL(g) {}



  void dfs(int idx, int par) {

    used[idx] = true;

    for(auto &to : this->g[idx]) {

      if(to == par) continue;

      if(!used[to] || this->ord[to] < this->ord[idx]) {

        tmp.emplace_back(minmax(idx, to));

      }

      if(!used[to]) {

        dfs(to, idx);

        if(this->low[to] >= this->ord[idx]) {

          bc.emplace_back();

          for(;;) {

            auto e = tmp.back();

            bc.back().emplace_back(e);

            tmp.pop_back();

            if(e.first == min(idx, to) && e.second == max(idx, to)) {

              break;

            }

          }

        }

      }

    }

  }



  void build() override {

    LL::build();

    used.assign(this->g.size(), 0);

    for(int i = 0; i < used.size(); i++) {

      if(!used[i]) dfs(i, -1);

    }

  }

};



template< int mod >

struct ModInt {

  int x;



  ModInt() : x(0) {}



  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}



  ModInt &operator+=(const ModInt &p) {

    if((x += p.x) >= mod) x -= mod;

    return *this;

  }



  ModInt &operator-=(const ModInt &p) {

    if((x += mod - p.x) >= mod) x -= mod;

    return *this;

  }



  ModInt &operator*=(const ModInt &p) {

    x = (int) (1LL * x * p.x % mod);

    return *this;

  }



  ModInt &operator/=(const ModInt &p) {

    *this *= p.inverse();

    return *this;

  }



  ModInt operator-() const { return ModInt(-x); }



  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }



  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }



  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }



  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }



  bool operator==(const ModInt &p) const { return x == p.x; }



  bool operator!=(const ModInt &p) const { return x != p.x; }



  ModInt inverse() const {

    int a = x, b = mod, u = 1, v = 0, t;

    while(b > 0) {

      t = a / b;

      swap(a -= t * b, b);

      swap(u -= t * v, v);

    }

    return ModInt(u);

  }



  ModInt pow(int64_t n) const {

    ModInt ret(1), mul(x);

    while(n > 0) {

      if(n & 1) ret *= mul;

      mul *= mul;

      n >>= 1;

    }

    return ret;

  }



  friend ostream &operator<<(ostream &os, const ModInt &p) {

    return os << p.x;

  }



  friend istream &operator>>(istream &is, ModInt &a) {

    int64_t t;

    is >> t;

    a = ModInt< mod >(t);

    return (is);

  }

};



