    http://snowytom.hatenablog.com/entry/2018/08/13/230545

    負進数にも対応

    12345, 10 -> [1, 2, 3, 4, 5]

*/

template<typename T>

std::vector<T> conv_base(T n, T base) {

    std::vector<T> ret;

    if (n == 0) {

        ret.push_back(0);

        return ret;

    }



    while (n != 0) {

        auto r = std::abs(n) % std::abs(base);

        ret.push_back(r);

        n -= r;

        n = n / base;;

    }



    std::reverse(std::begin(ret), std::end(ret));



    return ret;

}





int main()

{

    int64_t N, K;

    std::cin >> N >> K;



