        std::cin >> t;

        D.push_back(t);

    }



    for (;;++N) {

        auto b = conv_base(N, (int64_t)10);



        for (auto d: D) {

            auto pos = std::find(std::begin(b), std::end(b), d);

            if (pos != std::end(b)) {

                goto next;

            }

        }

        std::cout << N << std::endl;

        return 0;

    next:

        int a;

    }



    return 0;

}

