		pre[i]=a[query(a[i],r,1,n,1)];

		updata(1,n,1,a[i],i);

	}

	for(int i=1;i<=n;i++)if(pre[i])add(pre[i],a[i]);

	for(int i=1;i<=n;i++)if(pre[i]==0)ins(a[i]);

	cnt=0;

	for(int i=1;i<=n;i++){

		int u=heap[1];ans[u]=++cnt;pop();

		for(int j=head[u];j;j=l[j].next)ins(l[j].to);

	}

	for(int i=1;i<=n;i++)print(ans[i]);

